"use client";

import * as React from "react";
import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Margin Avatar: a 2rem round photo, or initials in oxblood on the soft oxblood
 * tint. Resize it with a size class; the initials follow the circle.
 */
const Avatar = React.forwardRef<HTMLSpanElement, WithClassName<AvatarPrimitive.Root.Props>>(
  ({ className, ...props }, ref) => (
    <AvatarPrimitive.Root
      ref={ref}
      data-slot="avatar"
      className={cn(
        "@container relative flex size-8 shrink-0 select-none overflow-hidden rounded-full bg-(--mark)",
        className,
      )}
      {...props}
    />
  ),
);
Avatar.displayName = "Avatar";

/** The photo, cropped to fill the circle. */
const AvatarImage = React.forwardRef<HTMLImageElement, WithClassName<AvatarPrimitive.Image.Props>>(
  ({ className, ...props }, ref) => (
    <AvatarPrimitive.Image
      ref={ref}
      data-slot="avatar-image"
      className={cn("aspect-square size-full object-cover", className)}
      {...props}
    />
  ),
);
AvatarImage.displayName = "AvatarImage";

/** Initials on the oxblood tint, shown while the photo loads or when it fails. */
const AvatarFallback = React.forwardRef<
  HTMLSpanElement,
  WithClassName<AvatarPrimitive.Fallback.Props>
>(({ className, ...props }, ref) => (
  <AvatarPrimitive.Fallback
    ref={ref}
    data-slot="avatar-fallback"
    className={cn(
      "flex size-full items-center justify-center rounded-full text-xs font-medium text-(--mark-foreground)",
      "@min-[3rem]:text-base",
      className,
    )}
    {...props}
  />
));
AvatarFallback.displayName = "AvatarFallback";

export { Avatar, AvatarImage, AvatarFallback };
